using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

namespace Astrea;

public class StartBattleStartEndTurnOmensHandler : ReferenceSingleton<StartBattleStartEndTurnOmensHandler>, OmenHandlerInterface
{
	[SerializeField]
	private float timeBetweenOmenFeedback = 1.5f;

	[NonSerialized]
	public Action TwistedScrollOmenAction;

	[NonSerialized]
	public List<Action> StartOfBattleBeforeSaviorPendantOmenActions = new List<Action>();

	[NonSerialized]
	public List<Action> StartOfBattleOmenActions = new List<Action>();

	[NonSerialized]
	public Action SaviorPendantOmenAction;

	[NonSerialized]
	public List<OmenInstance> RestartEndBattleOmens = new List<OmenInstance>();

	[NonSerialized]
	public List<OmenData> RestartEndBattleOmensDifficultyLevel = new List<OmenData>();

	[NonSerialized]
	public List<Action> EndOfBattleOmenActions = new List<Action>();

	[NonSerialized]
	public Action BlazarDiskStartOfBattleOmenAction;

	[NonSerialized]
	public Action BrightResonatorOmenAction;

	[NonSerialized]
	public Action BrightResonatorEndOfTurnOmenAction;

	[NonSerialized]
	public List<Action> StartOfTurnOmenCheckActivateActions = new List<Action>();

	[NonSerialized]
	public List<Action> StartOfTurnOmenActions = new List<Action>();

	[NonSerialized]
	public List<Action> StartOfTurnOmenBeforeLightShieldRemovalCheckActivateActions = new List<Action>();

	[NonSerialized]
	public List<Action> StartOfTurnOmenBeforeLightShieldRemovalOmenActions = new List<Action>();

	[NonSerialized]
	public List<OmenInstance> RestartStartTurnOmens = new List<OmenInstance>();

	[NonSerialized]
	public List<Func<int>> DrawAdditionalDieOmenActions = new List<Func<int>>();

	[NonSerialized]
	public List<Action> EndOfTurnOmenActions = new List<Action>();

	[NonSerialized]
	public List<Action> EndOfTurnOmenCheckActivateActions = new List<Action>();

	[NonSerialized]
	public Action PerpetualClockReceiveCorruptionOmenAction;

	[NonSerialized]
	public Action PerpetualClockOmenAction;

	[NonSerialized]
	public Func<int> CrypticMementoOmenAction;

	[NonSerialized]
	private WaitForEndOfFrame waitForEndOfFrame;

	public float TimeBetweenOmenFeedback => timeBetweenOmenFeedback;

	public void InitializeOmenHandler()
	{
		waitForEndOfFrame = new WaitForEndOfFrame();
		SubscribeDifficultyLevelEveryXTurnsEffect();
	}

	public IEnumerator ActivateStartOfBattleOmenActions()
	{
		List<OmenLogicActionFace> anomalyLevelStartingActions = ReferenceSingleton<AssetsReference>.Instance.AnomalyLevel.GetDifficultyLevelPlayerStartingAction();
		for (int l = 0; l < anomalyLevelStartingActions.Count; l++)
		{
			anomalyLevelStartingActions[l].OmenLogic.ActivateOmen(anomalyLevelStartingActions[l].ActionFace.BattleAction, anomalyLevelStartingActions[l].ActionFace.ActionValue, null, null);
			yield return new WaitForSeconds(timeBetweenOmenFeedback / 2f);
		}
		List<StartingEffect> anomalyLevelStartingEffects = ReferenceSingleton<AssetsReference>.Instance.AnomalyLevel.GetDifficultyLevelPlayerStartingEffects();
		for (int l = 0; l < anomalyLevelStartingEffects.Count; l++)
		{
			ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<UnitEffects>().AddEffect(anomalyLevelStartingEffects[l].Effect, anomalyLevelStartingEffects[l].EffectAmount);
			yield return new WaitForSeconds(timeBetweenOmenFeedback / 2f);
		}
		if (TwistedScrollOmenAction != null)
		{
			TwistedScrollOmenAction();
			yield return new WaitForSeconds(timeBetweenOmenFeedback);
		}
		for (int l = 0; l < StartOfBattleBeforeSaviorPendantOmenActions.Count; l++)
		{
			StartOfBattleBeforeSaviorPendantOmenActions[l]();
			yield return new WaitForSeconds(timeBetweenOmenFeedback);
		}
		if (SaviorPendantOmenAction != null)
		{
			SaviorPendantOmenAction();
			yield return new WaitForSeconds(timeBetweenOmenFeedback);
		}
		for (int l = 0; l < StartOfBattleOmenActions.Count; l++)
		{
			StartOfBattleOmenActions[l]();
			yield return new WaitForSeconds(timeBetweenOmenFeedback);
		}
		if (ReferenceSingleton<OrionOmensHandler>.Instance.IsHeartFragmentActiveAndActivateStartOfBattle())
		{
			yield return new WaitForSeconds(timeBetweenOmenFeedback);
		}
		BlazarDiskStartOfBattleOmenAction?.Invoke();
	}

	public void RestartOmensEndOfBattle()
	{
		for (int i = 0; i < EndOfBattleOmenActions.Count; i++)
		{
			EndOfBattleOmenActions[i]();
		}
		for (int j = 0; j < RestartEndBattleOmens.Count; j++)
		{
			OmenInstance omenInstance = RestartEndBattleOmens[j];
			omenInstance.OmenData.RestartCounter();
			omenInstance.OmenData.ToggleAlreadyUsed(toggle: false);
			omenInstance.SetIgnoreStartOfTurnUpdateOmenCounterForTheRestOfBattle(ignoreStartOfTurnUpdateOmenCounterForTheRestOfBattle: false);
			omenInstance.UpdateOmenCounter();
			omenInstance.StopBlinkingFeedback();
			omenInstance.EnableOmen();
		}
		for (int k = 0; k < RestartEndBattleOmensDifficultyLevel.Count; k++)
		{
			OmenData omenData = RestartEndBattleOmensDifficultyLevel[k];
			omenData.RestartCounter();
			omenData.ToggleAlreadyUsed(toggle: false);
		}
	}

	public IEnumerator ActivateBrightResonatorOmenAction()
	{
		if (BrightResonatorOmenAction != null)
		{
			yield return new WaitForSeconds(timeBetweenOmenFeedback / 2f);
			BrightResonatorOmenAction();
		}
	}

	public IEnumerator ActivateStartOfTurneforeLightShieldRemovalOmenActions()
	{
		for (int k = 0; k < StartOfTurnOmenBeforeLightShieldRemovalCheckActivateActions.Count; k++)
		{
			StartOfTurnOmenBeforeLightShieldRemovalCheckActivateActions[k]();
		}
		for (int j = 0; j < 3; j++)
		{
			yield return waitForEndOfFrame;
		}
		if (StartOfTurnOmenActions.Count > 0)
		{
			yield return new WaitForSeconds(timeBetweenOmenFeedback / 2f);
		}
		for (int j = 0; j < StartOfTurnOmenBeforeLightShieldRemovalOmenActions.Count; j++)
		{
			StartOfTurnOmenBeforeLightShieldRemovalOmenActions[j]();
			yield return new WaitForSeconds(timeBetweenOmenFeedback);
		}
		StartOfTurnOmenBeforeLightShieldRemovalOmenActions.Clear();
	}

	public void RestartOmensStartOfPlayerTurn()
	{
		for (int i = 0; i < RestartStartTurnOmens.Count; i++)
		{
			OmenInstance omenInstance = RestartStartTurnOmens[i];
			omenInstance.OmenData.RestartCounter();
			omenInstance.OmenData.ToggleAlreadyUsed(toggle: false);
			omenInstance.UpdateOmenCounter();
			omenInstance.EnableOmen();
			omenInstance.StopBlinkingFeedback();
		}
	}

	public IEnumerator ActivateStartOfTurnOmenActions()
	{
		for (int k = 0; k < StartOfTurnOmenCheckActivateActions.Count; k++)
		{
			StartOfTurnOmenCheckActivateActions[k]();
		}
		for (int j = 0; j < 3; j++)
		{
			yield return waitForEndOfFrame;
		}
		if (StartOfTurnOmenActions.Count > 0)
		{
			yield return new WaitForSeconds(timeBetweenOmenFeedback / 2f);
		}
		for (int j = 0; j < StartOfTurnOmenActions.Count; j++)
		{
			StartOfTurnOmenActions[j]();
			yield return new WaitForSeconds(timeBetweenOmenFeedback);
		}
		StartOfTurnOmenActions.Clear();
	}

	public int GetDrawAdditionalDieAmountOmens()
	{
		int num = 0;
		for (int i = 0; i < DrawAdditionalDieOmenActions.Count; i++)
		{
			num += DrawAdditionalDieOmenActions[i]();
		}
		return num;
	}

	private void SubscribeDifficultyLevelEveryXTurnsEffect()
	{
		ReferenceSingleton<AssetsReference>.Instance.AnomalyLevel.InitializeDifficultyLevelEveryXTurnsEffect();
	}

	public IEnumerator ActivateEndOfTurnOmenActions(Action discardDiceAction)
	{
		for (int k = 0; k < EndOfTurnOmenCheckActivateActions.Count; k++)
		{
			EndOfTurnOmenCheckActivateActions[k]();
		}
		for (int j = 0; j < 3; j++)
		{
			yield return waitForEndOfFrame;
		}
		if (EndOfTurnOmenActions.Count > 0 || PerpetualClockReceiveCorruptionOmenAction != null || BrightResonatorOmenAction != null)
		{
			yield return new WaitForSeconds(timeBetweenOmenFeedback / 2f);
		}
		for (int j = 0; j < EndOfTurnOmenActions.Count; j++)
		{
			EndOfTurnOmenActions[j]();
			yield return new WaitForSeconds(timeBetweenOmenFeedback);
		}
		if (BrightResonatorEndOfTurnOmenAction != null)
		{
			yield return new WaitForSeconds(timeBetweenOmenFeedback);
			BrightResonatorEndOfTurnOmenAction();
		}
		if (PerpetualClockReceiveCorruptionOmenAction != null)
		{
			PerpetualClockReceiveCorruptionOmenAction();
			yield return new WaitForSeconds(timeBetweenOmenFeedback);
		}
		PerpetualClockReceiveCorruptionOmenAction = null;
		BrightResonatorEndOfTurnOmenAction = null;
		EndOfTurnOmenActions.Clear();
		discardDiceAction?.Invoke();
	}

	public bool IsPerpetualClockOmenActiveActivateAction()
	{
		if (PerpetualClockOmenAction != null)
		{
			PerpetualClockOmenAction();
			return true;
		}
		return false;
	}

	public int GetCrypticMementoOmenActionAmount()
	{
		if (CrypticMementoOmenAction != null)
		{
			return CrypticMementoOmenAction();
		}
		return 0;
	}
}
